import type { IWorkflowEngineService, MedusaContainer } from "@medusajs/framework/types"
import { ContainerRegistrationKeys, Modules } from "@medusajs/framework/utils"
import { logger } from "../../../lib/logging"
import { ASYNC_JOB_MODULE } from "../../../modules/async-job"
import type AsyncJobModuleService from "../../../modules/async-job/service"

type Container = Pick<MedusaContainer, "resolve">

/** A run Medusa no longer works on: its record serves only a repeated call. */
const FINISHED_RUNS = ["done", "failed", "reverted"]

// Generated by Medusa's service factory, not declared on the module's type (2.21);
// a run's key is its workflow, transaction and run together
interface RunKey {
  workflow_id: string
  transaction_id: string
  run_id: string
}
interface WorkflowRunRecords {
  deleteWorkflowExecutions: (keys: RunKey[]) => Promise<void>
}

/**
 * Medusa keeps a finished checkout's run for three days so that completing
 * the same cart again answers with the same order (2.21 `complete-cart`,
 * `retention_time`); the run's context is the whole cart, the buyer's
 * e-mail, addresses and lines' metadata with it. The erased orders' carts'
 * finished runs go; a run still working is left to finish.
 */
export async function eraseCheckoutRuns(container: Container, cartIds: readonly string[]) {
  if (cartIds.length === 0) {
    return 0
  }
  // The run names its cart only inside its context (its input, `data.payload`),
  // which the engine's filters do not reach: the ids are read there, and the
  // runs deleted through the engine
  const pg = container.resolve(ContainerRegistrationKeys.PG_CONNECTION)
  const runs: RunKey[] = await pg<RunKey>("workflow_execution")
    .select("workflow_id", "transaction_id", "run_id")
    .whereNull("deleted_at")
    .whereIn("state", FINISHED_RUNS)
    .whereRaw(
      // An array binds as a Postgres array
      "(context->'data'->'payload'->>'id' = any(?::text[]) or context->'data'->'payload'->>'cart_id' = any(?::text[]))",
      [[...cartIds], [...cartIds]]
    )
  if (runs.length > 0) {
    const engine = container.resolve<IWorkflowEngineService>(Modules.WORKFLOW_ENGINE)
    await (engine as unknown as WorkflowRunRecords).deleteWorkflowExecutions(runs)
  }
  return runs.length
}

/**
 * The order list's files still kept (`order.export`, 7 days): each holds
 * every listed order's buyer, address and add-on texts, and which orders
 * one lists is not recorded. An erasure lets none of them stay; the list
 * is exported again from the panel.
 */
export async function expireOrderExports(container: Container) {
  const jobs = container.resolve<AsyncJobModuleService>(ASYNC_JOB_MODULE)
  const kept = await jobs.listAsyncJobs(
    { type: "order.export", result_file_id: { $ne: null } },
    { select: ["id", "result_file_id"], take: null }
  )
  for (const job of kept) {
    try {
      await container.resolve(Modules.FILE).deleteFiles(job.result_file_id ?? "")
    } catch {
      // Gone already: its record is cleared all the same
      logger.warn({ event: "legal.erasure_file_missing" })
    }
  }
  if (kept.length > 0) {
    await jobs.updateAsyncJobs(kept.map((job) => ({ id: job.id, result_file_id: null })))
  }
  return kept.length
}
